/// Registry entry for `thermal.tube_insert_model`.
static TUBE_INSERT_MODEL_CHECKS: &[SpecCheck] = &[
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "reynolds_number",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "zero is the laminar-tape state the capture pins; a negative Reynolds number is refused.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "prandtl_number",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the coiled-wire turbulent branch raises it to a negative power.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "twist_ratio",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a ratio is non-negative; the class floors it at two.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "tape_thickness",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the blockage factor divides by it; the class's own default is positive.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "tape_width_fraction",
            min: Some(0.0),
            min_inclusive: true,
            max: Some(1.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a width fraction is in `[0, 1]` of the bore.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "wire_diameter",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a diameter is non-negative, though no arithmetic reads it.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "wire_coil_pitch",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the coiled-wire `p/D` divides by it.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "matrix_density",
            min: Some(0.0),
            min_inclusive: true,
            max: Some(1.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the class's density factor is in `[0, 1]`.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "roughness_ratio",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a roughness height is non-negative.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "helix_angle",
            min: Some(0.0),
            min_inclusive: true,
            max: Some(90.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the correlations raise `angle/90` to a fractional power, so a negative angle answers NaN; 90 is the coil's limit.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "plain_heat_transfer_coefficient",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a coefficient cannot be negative.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "plain_pressure_drop",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a drop cannot be negative here; the enhancement multiplies it.",
        },
    },
];

